import { ChangeDetectionStrategy, Component } from '@angular/core';
import { MakeService } from '../../services/make-service';
import { FormGroup, FormBuilder, Validators, ReactiveFormsModule } from '@angular/forms';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';

@Component({
  selector: 'app-add-make',
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './add-make.html',
  styleUrl: './add-make.css',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class AddMake {
 makeForm: FormGroup;

constructor(private service: MakeService, private fb: FormBuilder, private router: Router) {
  this.makeForm = this.fb.group({
    name : ['', Validators.required],
  })
}
  onSubmit() {
    console.log('Submit clicked');
    if (this.makeForm.invalid) {
      this.makeForm.markAllAsTouched();
      return;
    }

    console.log('Form value:', this.makeForm.value);

    this.service.addProduct(this.makeForm.value).subscribe({
      next: () => {
        alert('✅ Make created successfully');
        this.resetForm();
        this.router.navigate(['/make'])
      },
      error: (err) => {
        console.error('❌ Upload failed', err);
        alert(err.error?.message || 'Upload failed. Please try again.');
      }
    });
  }

  private resetForm() {
    this.makeForm.reset();
    
  }
}
